91	/**
92	 * Run a READ through `gh`, treating an upstream failure as no answer rather than as
93	 * an answer of "no".
94	 *
95	 * GitHub returned `HTTP 504` for one `gh api repos/.../pulls/427` call and the run
96	 * died on it: the reviewer never started, and the pull request carried a red check
97	 * for a defect in neither the code nor the machinery. There is nothing to learn from
98	 * a 504 and nothing for an agent to do about it.
99	 *
100	 * Reads only, which is the whole reason this is a separate function rather than a
101	 * change to `gh` itself. A mutation that returns 502 may well have been applied, and
102	 * the invariants here are the kind a second attempt breaks -- one comment per run,
103	 * one dispatch per handoff. So the retry has to be asked for, by a caller that knows
104	 * its call changes nothing.
105	 *
106	 * Three attempts, widening, because the point is to outlast a blip rather than to
107	 * sit out an outage: a run holds a runner while it sleeps.
108	 */
109	export function ghRead(...args: string[]): RunResult {
110	  let result = gh(...args);
111	  for (const delay of [2_000, 6_000]) {
112	    if (result.code === 0 || !looksTransient(result)) return result;
113	    console.error(
114	      `::warning::gh ${args.slice(0, 2).join(" ")} failed transiently, retrying: ${result.stderr || result.stdout}`,
115	    );
116	    Bun.sleepSync(delay);
117	    result = gh(...args);
118	  }
119	  return result;
120	}
