157	export function ghJson<T = unknown>(...args: string[]): T | null {
158	  const { code, stdout, stderr } = gh(...args);
159	  if (code !== 0) {
160	    throw new Error(`gh ${args.join(" ")}: ${stderr || stdout}`);
161	  }
